function awardRecordsHTML(a){const hist=awardHighHistory.filter(x=>x.award_key===a.key),rows=hist.slice().sort((x,y)=>Number(y.score)-Number(x.score));return`<div class="lh-records"><h3>📈 All-Time Highs</h3><div class="lh-sub">Each team's highest recorded performance for this award. The timestamp is when that exact high was first captured and remains attached until a new high replaces it.</div>${rows.map((x,i)=>`<div class="lh-stat"><span><b>#${i+1}</b> ${esc(teamName(x.roster_id))}</span><span><small>${esc(x.detail||fmt(x.score))}</small><small style="display:block;color:var(--muted);margin-top:3px">Recorded ${esc(x.captured_at?new Date(x.captured_at).toLocaleString():'Timestamp unavailable')}</small></span></div>`).join('')||'<div class="lh-sub">No timestamped high has been captured yet.</div>'}</div>`}
