function loadedRosterRankingsHTML(a){return`<div class="lh-card"><div class="lh-action"><button class="secondary small" data-lh-rankings-back>← All Awards</button></div><h3 style="margin-top:12px">${esc(a.title)} — All 32 Teams</h3><div class="lh-sub">Current loaded-roster net value ranking. Use View chart to open the same league comparison pop-out.</div>${a.standings.map(x=>`<div class="lh-stat"><span><b>#${x.rank}</b> ${esc(teamName(x.roster_id))}</span><span><small>${esc(x.detail)}</small> <button class="secondary small" data-lh-loaded-roster>View chart</button></span></div>`).join('')}</div>`}
function weeklyCopy(t){const margin=Math.abs(t.points-t.opponent_points),projOk=t.projection_coverage>=Math.max(1,Math.ceil(t.starter_count*.65)),proj=t.projected||0;let opener=t.won?`${t.team_name} walked out with a ${t.points.toFixed(1)}–${t.opponent_points.toFixed(1)} win`:`${t.team_name} took a ${t.opponent_points.toFixed(1)}–${t.points.toFixed(1)} loss`;if(margin<8)opener+=', and this one was a fourth-quarter stomach ache.';else if(margin>35)opener+=t.won?', and it was never especially polite.':', and the scoreboard got ugly in a hurry.';else opener+='.';
 let expectation='';if(projOk){const delta=t.points-proj;if(t.won&&delta>10)expectation=` They beat their own projection by ${delta.toFixed(1)}, turning a normal Sunday into a statement.`;else if(t.won&&delta<-5)expectation=' They won without reaching their projected number — survival counts the same in the standings.';else if(!t.won&&delta>8)expectation=' The offense actually cleared projection and still lost. Sometimes the other roster simply has the flamethrower.';else if(!t.won&&delta<-10)expectation=` They finished ${Math.abs(delta).toFixed(1)} below projection, so this one felt more like a missed opportunity than bad luck.`;else expectation=' The final score landed reasonably close to the pregame expectation.'}
 let lineup='';if(t.best_bench&&t.worst_starter&&t.best_bench.points>t.worst_starter.points+8)lineup=` The Monday-morning quarterback department has a case: ${playerName(t.best_bench.id)} left ${t.best_bench.points.toFixed(1)} on the bench while ${playerName(t.worst_starter.id)} gave the lineup ${t.worst_starter.points.toFixed(1)}.`;else if(t.worst_starter)lineup=' There was no screamingly obvious bench decision that single-handedly explains the result.';
 const moves=t.transactions?.length?` They were active too, logging ${t.transactions.length} transaction${t.transactions.length===1?'':'s'} during the week.`:' The front office kept the phone mostly quiet this week.';
 return opener+expectation+lineup+moves}
function rumorFor(t,w){const a=['has a suspiciously strong opinion about airport carpet','refuses to rank breakfast foods before noon','believes every road trip needs one unnecessary gas-station purchase','keeps a mental ranking of grocery-store parking lots','claims the best game-day snack is whichever one requires the least cleanup','has been researching a hobby they are absolutely not ready to admit is becoming serious','judges restaurants partly by the quality of their ice','would rather reorganize a closet than watch a preseason recap'];let h=0;for(const ch of String(t.manager_name||t.roster_id)+String(w))h=(h*31+ch.charCodeAt(0))>>>0;return a[h%a.length]}
function txReview(t){if(!t.transactions?.length)return 'GM '+t.manager_name+' kept the transaction wire quiet. That is defensible if the roster is healthy, although inactivity gets less charming if the same weak spot survives another Sunday.';const bits=t.transactions.slice(0,5).map(x=>{const a=(x.adds||[]).map(playerName),d=(x.drops||[]).map(playerName);return(a.length?'added '+a.join(', '):'')+(a.length&&d.length?' and ':'')+(d.length?'moved on from '+d.join(', '):'')}).filter(Boolean);return 'GM '+t.manager_name+' logged '+t.transactions.length+' move'+(t.transactions.length===1?'':'s')+(bits.length?': '+bits.join('; '):'.')+'. The useful question is whether those moves attacked the positions that actually cost points.'}
