function install(){addStyles();const tabs=document.querySelector('.tabs'),main=document.querySelector('main');if(!tabs||!main){setTimeout(install,100);return}let s=document.getElementById('leagueHub');if(!s){s=document.createElement('section');s.id='leagueHub';s.className='tab';s.hidden=true;main.appendChild(s)}if(!s.querySelector('#leagueHubContent'))s.innerHTML='<div class="card"><div class="lh-head"><h2>Fleeced! League Hub</h2><p>Your league broadcast center—weekly matchup stories, awards, trade legends, and manager résumés.</p></div><div class="lh-nav"><button type="button" class="active" data-lh-view="daily">Fleeced Daily</button><button type="button" data-lh-view="awards">Awards</button><button type="button" data-lh-view="hall">Hall of Fleeced</button><button type="button" data-lh-view="managers">Managers</button></div><div id="leagueHubContent"><div class="empty">Open League Hub to load league intelligence.</div></div></div>';wireSection(s);let b=document.querySelector('.tabs button[data-tab="leagueHub"]');if(!b){b=document.createElement('button');b.type='button';b.dataset.tab='leagueHub';b.textContent='League Hub';tabs.appendChild(b)}if(b.dataset.lhWired!=='1'){b.dataset.lhWired='1';b.addEventListener('click',()=>{activate('leagueHub');render(currentView)})}installed=true;if(b.classList.contains('active')&&!s.hidden)render(currentView)}
